class Walker {
  constructor(x, y, step) {
    this.x = x;
    this.y = y;
    this.step = step;
    this.size = this.step / random(1, 3);
    this.color1 = generateColor(1);
    this.color2 = generateColor(1);
    this.rad = this.step / 3;
    this.w = random(0, 100);
    this.shape = random(["line", "point"]);
  }

  draw(pg) {
    let ranAng1 = random(0, 2 * PI);
    let ranAng2 = random(0, 2 * PI);

    let oldX = this.x;
    let oldY = this.y;

    //this.x += this.step * cos(ranAng1);
    //this.y += this.step * sin(ranAng2);

		this.x += this.step*random([-1,0,1]);
		this.y += this.step*random([-1,0,1]);

    pg.strokeWeight(this.w);
    pg.stroke(this.color2);

    this.w *= 0.95;
    this.rad *= 0.95;

    if (this.shape == "line") {
      pg.line(oldX, oldY, this.x, this.y);
      if (this.w > 10) {
        pg.strokeWeight(this.w / 2);
        pg.stroke(this.color1);
        pg.line(oldX, oldY, this.x, this.y);
      }
    } else {
      pg.fill(this.color2);
      pg.circle(this.x, this.y, this.rad);
      pg.fill(this.color1);
      pg.circle(this.x, this.y, this.rad / 2);
    }
  }
}

function generateColor(scale) {
  let temp = color(colors[floor(random(0, colors.length))]);
  let myColor = color(
    hue(temp) + randomGaussian() * scale,
    saturation(temp) + randomGaussian() * scale,
    brightness(temp) + randomGaussian() * scale,
    random(100, 100)
  );
  return myColor;
}

