function buildCanvasTexture(w, h, opt = {}) {
  const {
    cell = 3,
    jitter = 0.25,
    alpha = 20,
    grain = 10,
    vignet = 0.12
  } = opt;

  const tex = createGraphics(w, h);
  tex.pixelDensity(1);
  tex.loadPixels();


  const freqX = 1 / (cell * 1.0);
  const freqY = 1 / (cell * 1.0);

  function vignetteFactor(x, y) {
    const nx = (x / (w - 1)) * 2 - 1;
    const ny = (y / (h - 1)) * 2 - 1;
    const r2 = nx * nx + ny * ny;       // 0 en centro, ~2 en esquinas
    const v = 1 - vignet * r2;          // reduce en las orillas
    return constrain(v, 0.7, 1);        // no la dejes muy fuerte
  }


  for (let y = 0; y < h; y++) {
    // Tramas base (ondas senoidales + ruido leve)
    const rowWeft = 0.5 + 0.5 * Math.sin(y * freqY * TWO_PI + 0.7);   // horizontal
    for (let x = 0; x < w; x++) {
      const colWarp = 0.5 + 0.5 * Math.sin(x * freqX * TWO_PI + 1.1); // vertical


      const cross = (rowWeft * colWarp);
      const j = (random() - 0.5) * 2 * jitter; // [-jitter, +jitter]
      let intensity = cross + j;


      if (grain > 0) {
        intensity += (random() - 0.5) * (grain / 255.0);
      }

      intensity = constrain(pow(constrain(intensity, 0, 1), 0.9), 0, 1);

      // aplica viñeta
      intensity *= vignetteFactor(x, y);


      const g = floor(255 * intensity);
      const a = alpha;

      const idx = 4 * (y * w + x);
      tex.pixels[idx]     = g;
      tex.pixels[idx + 1] = g;
      tex.pixels[idx + 2] = g;
      tex.pixels[idx + 3] = a;
    }
  }
  tex.updatePixels();


  tex.push();
  tex.stroke(255, 12);                    
  tex.strokeWeight(1);
  for (let yy = 0; yy < h; yy += cell * 8) tex.line(0, yy, w, yy);       
  for (let xx = 0; xx < w; xx += cell * 8) tex.line(xx, 0, xx, h);      
  tex.pop();

  return tex;
}


